'use strict';
(async () => {
const D = window.STUDY_DATA;
const root = document.getElementById('app');
if(!D){window.StudyUI.loadError(root,'题库未能加载，请重新打开。');return;}
const KEY = 'ruc802.practice.v1';
const remote=await window.createServerStore(D);
window.RemoteStore=remote;
if(location.hash.startsWith('#token='))history.replaceState(null,'',location.pathname+location.search);
const persistenceMessage=()=>remote.active?remote.message:(storageOK?'已保存在此浏览器':'未能保存，请导出备份');
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.getElementById('main')?.focus();});
const all = D.subjects.flatMap(s => s.questions.map(q => ({...q, subject:s.key, subjectName:s.name})));
const byId = Object.assign(Object.create(null),Object.fromEntries(all.map(q => [q.id,q])));
const sub = Object.fromEntries(D.subjects.map(s => [s.key,s]));
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nowDate = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const validDate = d => /^\d{4}-\d{2}-\d{2}$/.test(d) && Number.isFinite(Date.parse(d+'T00:00:00Z')) && new Date(d+'T00:00:00Z').toISOString().slice(0,10)===d;
const dayDelta = (a,b) => Math.floor((Date.parse(a+'T00:00:00Z')-Date.parse(b+'T00:00:00Z'))/86400000);
const dateFor = n => new Date(Date.parse(state.start+'T00:00:00Z')+(n-1)*86400000).toISOString().slice(0,10);
const uid = () => Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9);
let photoExportUnavailable=false;
let operation={busy:false,message:'',state:'pending',done:0,total:0,action:''};
let storageOK=true, toastTimer, filter={subject:'micro',group:'all',status:'all',search:'',page:1}, selectedDay;
const readingDefaults=()=>({size:19,face:'serif',focus:false});
const fresh=remote.model.fresh,cleanWork=remote.model.cleanWork;
function rememberQuestion(){const s=state.session;if(s){s.work??={};s.work[s.ids[s.index]]={seconds:elapsed(),revealed:s.revealed,hint:s.hint,ratingId:s.ratingId};}}
function applyReading(){document.documentElement.style.setProperty('--reading-size',state.reading.size+'px');document.body.dataset.face=state.reading.face;document.body.classList.toggle('reading-focus',['practice','recall-study'].includes(route())&&state.reading.focus);}
function readingBar(){return `<div class="reading-bar" aria-label="阅读设置"><div class="reading-size" role="group" aria-label="字号">${[[17,'小'],[19,'标准'],[21,'大']].map(([size,label])=>`<button data-action="font-size" data-size="${size}" aria-label="${label}字号" aria-pressed="${state.reading.size===size}" class="${state.reading.size===size?'selected':''}">${label}</button>`).join('')}</div><label><span class="visually-hidden">正文字体</span><select id="reading-face"><option value="serif" ${state.reading.face==='serif'?'selected':''}>宋体阅读</option><option value="sans" ${state.reading.face==='sans'?'selected':''}>黑体阅读</option></select></label><button class="focus-toggle" data-action="focus" aria-pressed="${state.reading.focus}">${state.reading.focus?'退出专注':'专注阅读'}</button></div>`;}
function readingLocation(id){document.getElementById(id)?.scrollIntoView({block:'start'});}
const validate=remote.model.validate;
let state;
if(remote.active)state=remote.initialState;
else try{const raw=localStorage.getItem(KEY);state=raw?validate(JSON.parse(raw)):fresh();}catch{state=fresh();storageOK=false;}
function save(){rememberQuestion();if(remote.active)return remote.save(state);try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;document.querySelector('.local-status')?.replaceChildren(document.createTextNode('未能保存，请导出备份'));}return storageOK;}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}
function showOperation(message,patch={}){
 operation={...operation,...patch,message};mountOperation();
}
function beginOperation(action,message){if(operation.busy){toast('正在处理上一项操作，请稍候。');return false;}showOperation(message,{busy:true,state:'pending',done:0,total:0,action});return true;}
function finishOperation(message,isError=false){showOperation(message,{busy:false,state:isError?'error':'done'});}
function mountOperation(){
 for(const area of document.querySelectorAll('[data-operation-status]')){
  area.hidden=!operation.message;area.dataset.state=operation.state;area.setAttribute('aria-busy',String(operation.busy));
  if(!area.firstChild)area.innerHTML='<p></p><progress hidden aria-label="备份图片处理进度"></progress>';
  const text=area.querySelector('p');if(text.textContent!==operation.message)text.textContent=operation.message;
  const progress=area.querySelector('progress');progress.hidden=!operation.busy||!operation.total;progress.max=operation.total||1;progress.value=operation.done;
 }
 for(const button of document.querySelectorAll('[data-action="export"],[data-action="export-progress"],[data-action="import"],[data-action="migrate-local"]')){button.disabled=operation.busy;button.setAttribute('aria-busy',String(operation.busy&&button.dataset.action===operation.action));}
 const dialog=document.querySelector('.interaction-dialog[aria-busy="true"]');if(dialog&&operation.busy){const status=dialog.querySelector('.dialog-status');status.textContent=operation.message;status.classList.toggle('is-error',operation.state==='error');const progress=dialog.querySelector('.dialog-progress');if(progress){progress.hidden=!operation.total;progress.max=operation.total||1;progress.value=operation.done;}}
}

const latest = id => [...state.records].reverse().find(r=>r.qid===id);
const gradeText = r => r===2?'会做':r===1?'不熟':'不会';
const gradeClass = r => r===2?'done':r===1?'weak':'wrong';
function todayDay(){return Math.max(1,Math.min(50,dayDelta(nowDate(),state.start)+1));}
selectedDay=todayDay();
function dayRecord(id,day){return [...state.records].reverse().find(r=>r.qid===id&&r.day===day);}
function icon(name){const paths={today:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-14 5h3m4 0h3"/>',bank:'<path d="M4 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4zM14 5h6v14h-6"/>',wrong:'<path d="M8 3h8l5 5v13H3V3h5m5 0v6h7M8 12l8 6m0-6-8 6"/>',favorites:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',materials:'<path d="M4 3h10l6 6v12H4zM14 3v6h6M8 13h8m-8 4h6"/>',history:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',settings:'<path d="M4 7h16M4 17h16M9 4v6m7 4v6"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.bank}</svg>`;}
const pages={today:'今日安排',bank:'刷题训练',recall:'公式与背诵',review:'复盘与记录',wrong:'错题复做',favorites:'我的收藏',materials:'资料库',history:'练习记录',settings:'设置与备份',practice:'正在练习','recall-study':'正在背诵'};
function route(){const key=location.hash.slice(1)||'today';return Object.hasOwn(pages,key)?key:'today';}
function shell(content,page){const wrong=all.filter(q=>{let r=latest(q.id);return r&&r.rating<2;}).length;
 const items=['today','bank','recall','review','materials','settings'];
 const activePage=page==='practice'?'bank':page==='recall-study'?'recall':['wrong','favorites','history'].includes(page)?'review':page;
 root.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#today"><img src="icon.svg" alt=""><span>802练习室</span></a><nav class="nav" aria-label="主导航">${items.map(k=>`<a href="#${k}" ${activePage===k?'class="active" aria-current="page"':''}>${icon(k==='recall'?'bank':k==='review'?'history':k)}${pages[k]}${k==='wrong'&&wrong?`<span class="count">${wrong}</span>`:''}${k==='favorites'&&state.favorites.length?`<span class="count">${state.favorites.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-foot"><p>人大经济学综合</p><p>刷题、背诵与复盘。<br>把知识用回题目里。</p><p>${remote.active?'记录和照片保存在服务器。<br><a href="#settings">备份与旧数据迁移</a>':'记录保存在当前浏览器。<br><a href="#settings">导出备份，带走进度</a>'}</p></div></aside><main id="main" class="main" tabindex="-1"><div class="topbar"><div class="breadcrumb">人大802 / ${pages[page]}</div><span class="local-status" role="status" aria-live="polite" aria-atomic="true">${remote.active?remote.message:(storageOK?'进度保存在此浏览器':'未能保存，请导出备份')}</span><span data-access-controls></span></div><div data-server-notice></div><section class="operation-status" data-operation-status role="status" aria-live="polite" hidden></section>${!remote.active&&!storageOK?'<div class="notice">浏览器未能读取或保存记录。请先在“设置与备份”导出当前记录，避免关闭后丢失。</div>':''}${content}</main></div>`;
 root.setAttribute('aria-busy','false');const heading=root.querySelector('h1');if(heading)heading.tabIndex=-1;applyReading();remote.mount();mountOperation();
}
function chip(id,record,attrs=''){return `<button class="qchip ${record?gradeClass(record.rating):''}" ${attrs} title="${esc(byId[id].title)}${record?' / '+gradeText(record.rating):''}">${id}</button>`;}
function home(){const day=D.plan.days[selectedDay-1];const done=all.filter(q=>dayRecord(q.id,selectedDay)).length;const distinct=new Set(state.records.map(r=>r.qid)).size;const rawDay=dayDelta(nowDate(),state.start)+1;
 const timeMessage=rawDay<1?'计划尚未开始，可先做第1天。':rawDay>50?'已超过50天，可选任意一天继续复做。':`今天是计划第${todayDay()}天。`;
 shell(`<div class="page-heading"><div><h1>先练一道，再补一个断点。</h1><p>先闭卷作答，再对照解答。三科各10道，连续小问算一道整题。</p></div>${state.session?'<button class="btn ink" data-action="resume">继续上次练习</button>':''}</div>${learning.homePanel()}<h2 class="daily-heading">每日整题训练</h2><section class="paper"><div class="today-head"><div class="day-select"><div><div class="day-number">第 ${selectedDay} 天<span>/ 50天</span></div><div class="phase">${esc(day.phase)} · 第${Math.ceil(selectedDay/10)}轮</div></div><label><span class="visually-hidden">选择计划日</span><button class="day-step" data-action="day-prev" aria-label="上一计划日" ${selectedDay===1?'disabled':''}>‹</button><select id="day-select" aria-label="选择计划日">${D.plan.days.map(d=>`<option value="${d.day}" ${d.day===selectedDay?'selected':''}>第${d.day}天</option>`).join('')}</select><button class="day-step" data-action="day-next" aria-label="下一计划日" ${selectedDay===50?'disabled':''}>›</button></label></div><div class="date-control"><span>${dateFor(selectedDay)}</span><button class="btn flat" data-action="today">回到今天</button></div></div>${D.subjects.map((s,i)=>{const ids=day[s.key+'_refs'];const count=ids.filter(id=>dayRecord(id,selectedDay)).length;return `<div class="subject-row"><div><div class="subject-title">${s.name}</div><div class="subject-topic">${selectedDay<=10?esc(byId[ids[0]].group_title):'跨组整题复做'}</div></div><div class="subject-pills">${ids.map(id=>chip(id,dayRecord(id,selectedDay),`data-action="day-question" data-id="${id}" data-sub="${s.key}"`)).join('')}</div><div class="row-action"><div class="small muted">已作答 ${count}/10 · 约${day.minutes[i]}分钟</div><button class="btn ${count<10?'primary':''}" data-action="start-day" data-sub="${s.key}">${count===10?'再做一遍':'开始练习'}</button></div></div>`;}).join('')}<div class="study-footer"><span>当天已自评 ${done}/30题。另留60分钟订正；建议总用时约${(day.planned_minutes/60).toFixed(1)}小时，休息另计。</span><a href="#settings">调整开始日期</a></div></section><div class="under-grid"><section class="quiet-panel"><h3>这一轮，练到哪里了</h3><div class="progress-summary"><span>累计接触 ${distinct}/300道独立题</span><span>已自评 ${state.records.length}次</span></div><div class="progress-line"><i style="width:${distinct/3}%"></i></div><p>每科100题各做5轮，50天共1500次作答。题号重复表示复做，不算新增题。</p></section><section class="quiet-panel"><h3>复盘时，抓住一个断点</h3><p>条件哪里漏了，推导哪里断了，论证哪里没接上。把“不熟”和“不会”的题留到错题复做。</p><p>${timeMessage}</p><a href="#wrong" class="small">打开错题复做</a></section></div>`,'today');
}
function filtered(page){let result=all.filter(q=>q.subject===filter.subject);
 if(page==='wrong') result=result.filter(q=>{let r=latest(q.id);return r&&r.rating<2;});
 if(page==='favorites')result=result.filter(q=>state.favorites.includes(q.id));
 if(filter.group!=='all')result=result.filter(q=>q.group===filter.group);
 if(filter.status!=='all')result=result.filter(q=>{const r=latest(q.id);return filter.status==='new'?!r:filter.status==='good'?r?.rating===2:r&&r.rating<2;});
 const key=filter.search.trim().toLowerCase();if(key)result=result.filter(q=>(q.id+' '+q.title+' '+q.group_title+' '+q.prompt_md).toLowerCase().includes(key));return result;
}
function library(page){const list=filtered(page);const size=20;filter.page=Math.min(filter.page,Math.max(1,Math.ceil(list.length/size)));const view=list.slice((filter.page-1)*size,filter.page*size);const subtitle={bank:'按专题找题，也可以随机抽取10道。完整解答在作答页中查看。',wrong:'按最近一次自评收集“不熟”和“不会”。复做后选“会做”，即可移出。',favorites:'把值得反复推敲的题留在这里。收藏与错题分别记录。'}[page];
 shell(`<div class="page-heading"><div><h1>${pages[page]}</h1><p>${subtitle}</p></div><button class="btn primary" data-action="random" ${list.length?'':'disabled'}>随机练${Math.min(10,list.length)||10}题</button></div><div class="tabs" role="group" aria-label="选择科目">${D.subjects.map(s=>`<button class="tab ${s.key===filter.subject?'active':''}" data-action="subject" data-sub="${s.key}" aria-pressed="${s.key===filter.subject}">${s.name}</button>`).join('')}</div><div class="toolbar"><label class="search"><span class="visually-hidden">搜索题号、题名或题干</span><input id="search" type="search" placeholder="搜索题号、题名或题干" value="${esc(filter.search)}"></label><label><span class="visually-hidden">筛选专题</span><select id="group-filter"><option value="all">全部专题</option>${sub[filter.subject].groups.map(g=>`<option value="${g.id}" ${filter.group===g.id?'selected':''}>${g.id} ${esc(g.title)}</option>`).join('')}</select></label><label><span class="visually-hidden">筛选掌握状态</span><select id="status-filter">${[['all','全部状态'],['new','未作答'],['weak','不熟 / 不会'],['good','会做']].map(([v,t])=>`<option value="${v}" ${filter.status===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="bank-meta"><span>找到 ${list.length} 道题${filter.group!=='all'?' · 本专题10道':''}</span><button class="btn flat" data-action="start-filter" ${list.length?'':'disabled'}>${filter.group!=='all'?'练习本专题':'按顺序练习'}</button></div><section class="paper">${view.length?`<ul class="question-list">${view.map(q=>{const r=latest(q.id);return `<li class="question-row"><span class="qid">${q.id}</span><div><h3>${esc(q.title)}${r?`<span class="status-pill ${r.rating===2?'good':'bad'}">${gradeText(r.rating)}</span>`:''}</h3><p>${esc(q.group_title)} · 建议${q.minutes}分钟 · ${esc(q.kind)}</p></div><div class="row-buttons"><button class="star ${state.favorites.includes(q.id)?'on':''}" data-action="favorite" data-id="${q.id}" aria-label="${state.favorites.includes(q.id)?'取消收藏':'收藏'} ${q.id}" aria-pressed="${state.favorites.includes(q.id)}">${state.favorites.includes(q.id)?'★':'☆'}</button><button class="btn" data-action="single" data-id="${q.id}">开始作答</button></div></li>`;}).join('')}</ul>`:`<div class="empty"><h2>${page==='wrong'?'这里暂时没有错题':page==='favorites'?'还没有收藏的题':'没有找到符合条件的题'}</h2><p>${filter.search||filter.group!=='all'||filter.status!=='all'?'试试清除搜索或更换筛选条件。':'完成作答后可以自评、收藏，记录会出现在这里。'}</p><button class="btn" data-action="clear-filter">清除筛选</button></div>`}</section>${list.length>size?`<div class="pagination"><button class="btn" data-action="prev-page" ${filter.page===1?'disabled':''}>上一页</button><span class="small muted">第${filter.page}/${Math.ceil(list.length/size)}页</span><button class="btn" data-action="next-page" ${filter.page*size>=list.length?'disabled':''}>下一页</button></div>`:''}`,page);
}
function elapsed(){const s=state.session;return s?Math.floor(s.seconds+(s.startedAt?(Date.now()-s.startedAt)/1000:0)):0;}
function pause(){const s=state.session;if(s?.startedAt){s.seconds=elapsed();s.startedAt=null;save();}}
function flushDraft(){const el=document.getElementById('draft');if(el&&state.session){state.drafts[state.session.ids[state.session.index]]=el.value;save();}}
function navigate(hash){flushDraft();pause();if(location.hash==='#'+hash)render();else location.hash=hash;}
function start(ids,mode,day=null,index=0){flushDraft();pause();state.session={ids:[...ids],index,mode,day,seconds:0,startedAt:null,revealed:false,hint:false,ratingId:null,work:{}};save();navigate('practice');}
function move(index){const s=state.session;if(!s||index<0||index>=s.ids.length||index===s.index)return;flushDraft();pause();rememberQuestion();const work=s.work[s.ids[index]]||{};Object.assign(s,{index,startedAt:null,...cleanWork(work,s.ids[index],state.records)});save();render();window.scrollTo({top:0});document.querySelector('.exercise-heading h1')?.focus({preventScroll:true});}
function clockText(seconds){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function knowledgeReview(q){return `<section class="knowledge-review"><h2>本题知识点</h2><p class="small muted">对照本题用法，回忆每个知识点的条件与联系。</p><ul class="knowledge-list">${q.solution.knowledge.map(item=>`<li><h3 class="rich">${item.title_html}</h3><div class="rich">${item.explanation_html}</div><div class="actions">${item.card_ids.map(id=>`<button class="btn" data-action="recall-card" data-id="${id}" data-return="practice">回忆：${esc(D.recall.cards.find(c=>c.id===id).title)}</button>`).join('')}</div></li>`).join('')}</ul><section class="knowledge-chain"><h3>把本题再串一遍</h3><div class="rich">${q.solution.recap_html}</div></section></section>`;}
function practice(){const s=state.session;if(!s){navigate('bank');return;}const q=byId[s.ids[s.index]];const r=s.ratingId?state.records.find(r=>r.id===s.ratingId):null;const favorite=state.favorites.includes(q.id);
 shell(`<div class="practice-layout"><aside class="paper question-rail"><div class="rail-title">${esc(s.mode)}${s.day?' / 第'+s.day+'天':''}</div><div class="rail-ids">${s.ids.map((id,i)=>{const rec=s.day?dayRecord(id,s.day):latest(id);return `<button class="qchip ${rec?gradeClass(rec.rating):''} ${i===s.index?'current':''}" data-action="jump" data-index="${i}" ${i===s.index?'aria-current="step"':''} title="${esc(byId[id].title)}">${id}</button>`;}).join('')}</div><div class="rail-note">绿色：会做<br>浅棕：不熟　浅红：不会<br>每题对照解答后自行评估。</div><div class="rail-progress">本组已评 ${s.ids.filter(id=>s.work?.[id]?.ratingId).length}/${s.ids.length}</div></aside><div class="exercise"><div class="exercise-top"><button class="btn flat" data-action="back">返回${s.day?'计划':'题库'}</button><div class="clock"><span id="timer" aria-label="本题用时">${clockText(elapsed())}</span><button data-action="timer">${s.startedAt?'暂停计时':'开始计时'}</button></div></div>${readingBar()}<article class="paper exercise-paper"><div class="exercise-meta"><span class="q-id">${q.id}</span><span>${q.subjectName}</span><span>第${q.group}组</span><span>建议${q.minutes}分钟</span><span>${q.kind}</span></div><div class="exercise-heading"><h1 tabindex="-1" id="question-heading">${esc(q.title)}</h1><button class="star ${favorite?'on':''}" data-action="favorite" data-id="${q.id}" aria-label="${favorite?'取消收藏':'收藏'} ${q.id}" aria-pressed="${favorite}">${favorite?'★':'☆'}</button></div><div class="rich prompt" id="question-prompt">${q.prompt_html}</div>${q.diagrams?.length?'<aside class="diagram-drawing-hint">这道题可先画辅助图：标清对象、条件和关键关系，核对解答时再逐步对照。</aside>':''}<div id="my-writing">${photos.render(q.id)}</div>${state.drafts[q.id]?`<details class="legacy-draft"><summary>查看历史文字作答</summary><pre>${esc(state.drafts[q.id])}</pre></details>`:''}<div class="exercise-buttons"><button class="btn" data-action="hint" aria-expanded="${s.hint}">${s.hint?'收起提纲':'给我一点提示'}</button><button class="btn primary" data-action="reveal" aria-expanded="${s.revealed}">${s.revealed?'收起完整解答':'作答结束，核对解答'}</button></div>${s.hint&&!s.revealed?`<section class="hint-box"><h2>作答提纲</h2><div class="rich">${q.outline_html}</div></section>`:''}${s.revealed?`<section class="answer-section" id="answer"><div class="answer-nav"><button data-action="read-question">回看题目</button><button data-action="read-draft">查看作答照片</button></div><span class="answer-label">对照自己的推导与论证</span><h2>作答提纲</h2><div class="rich">${q.outline_html}</div>${window.StudyDiagrams.render(q)}<h2>规范解题过程</h2><ol class="solution-steps">${q.solution.steps.map((step,index)=>`<li class="solution-step"><div class="step-heading"><span>步骤 ${index+1}</span></div><div class="rich">${step.body_html}</div></li>`).join('')}</ol><div class="pitfalls"><h3>条件与易错</h3><div class="rich">${q.pitfalls_html}</div></div>${knowledgeReview(q)}<section class="self-check"><h3>这道题，你掌握了吗？</h3><p>选择后保存本次作答。“不熟”和“不会”自动进入错题复做；可修改本次自评。</p><div class="rating-buttons">${[[0,'不会，需重做','bad'],[1,'不熟，有断点','medium'],[2,'会做，已掌握','']].map(([n,t,c])=>`<button class="rating ${c} ${r?.rating===n?'selected':''}" data-action="rate" data-rating="${n}" aria-pressed="${r?.rating===n}">${t}</button>`).join('')}</div>${r?`<p style="margin:12px 0 0">本次已记录：${gradeText(r.rating)}。${s.day?'已计入第'+s.day+'天的对应题目。':'本次为自由练习。'}</p><button class="btn primary rating-next" data-action="next">${s.index===s.ids.length-1?'完成本组，查看记录':(remote.active?'继续下一题':'已保存，下一题')}</button>`:''}</section></section>`:''}${learning.practicePanel(q)}<details class="source"><summary>题源与材料说明</summary>${q.source_refs.map(ref=>`<p>${esc(ref.exam_id)}<br>${esc(ref.source.split('/').pop())}，PDF物理页 ${esc(ref.pages)}。<br>${esc(ref.note)}</p>`).join('')}<p>本题为${q.kind}，参数与条件以本题为准。来源原PDF请在本地资料中查阅。</p></details></article><div class="exercise-bottom"><button class="btn" data-action="prev" ${s.index===0?'disabled':''}>上一题</button><span>第 ${s.index+1} / ${s.ids.length} 题</span><button class="btn ink" data-action="next">${s.index===s.ids.length-1?'结束本组':'下一题'}</button></div></div></div>`,'practice');
 const current=root.querySelector('.qchip.current'),rail=current?.parentElement;if(rail&&getComputedStyle(rail).display==='flex'){const box=current.getBoundingClientRect(),bounds=rail.getBoundingClientRect();rail.scrollLeft+=box.left-bounds.left-(rail.clientWidth-box.width)/2;}
 photos.refresh(q.id);
}
function materials(){shell(`<div class="page-heading"><div><h1>资料库</h1><p>在线回忆请进入公式与背诵；这里保留配套PDF与Excel，便于查阅、打印。</p></div><a class="btn primary" href="#recall">打开公式与背诵</a></div><div class="material-list">${D.materials.map(m=>`<section class="paper material"><span class="material-tag">${esc(m.tag)}</span><h2>${esc(m.title)}</h2><p>${esc(m.description)}</p><div class="actions">${m.files.map(f=>`<a class="btn ${f.label==='打开PDF'?'primary':''}" href="${f.url}" target="_blank" rel="noopener">${esc(f.label)}</a>`).join('')}</div></section>`).join('')}</div><p class="small muted" style="margin-top:24px">题目采用真题结构改编、条件变式与综合模拟；来源信息见每题底部。网站未改写题库正文。</p>`,'materials');}
let historyPage=1;
function history(){const records=[...state.records].reverse();historyPage=Math.min(historyPage,Math.max(1,Math.ceil(records.length/30)));shell(`<div class="page-heading"><div><h1>每一次作答，都留一笔。</h1><p>这里记录自评与本题计时。只查看答案不会计入已作答。点击题号可以复习该题。</p></div><button class="btn" data-action="export">导出全部记录</button></div><div class="stats-inline"><span><strong>${records.length}</strong>次作答</span><span><strong>${new Set(records.map(r=>r.qid)).size}</strong>道独立题</span><span><strong>${Math.round(records.reduce((a,r)=>a+r.seconds,0)/60)}</strong>分钟计时</span></div><section class="paper table-wrap">${records.length?`<table class="record-table"><thead><tr><th>题号</th><th>题目</th><th>自评</th><th>安排</th><th>用时</th><th>时间</th></tr></thead><tbody>${records.slice((historyPage-1)*30,historyPage*30).map(r=>`<tr><td><button data-action="single" data-id="${r.qid}" style="color:var(--green)">${r.qid}</button></td><td>${esc(byId[r.qid].title)}</td><td>${gradeText(r.rating)}</td><td>${r.day?'第'+r.day+'天':'自由练习'}</td><td>${clockText(r.seconds)}</td><td>${new Date(r.at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><h2>还没有完成的练习</h2><p>做一道题，对照答案后选择自评，这里就会留下记录。</p><a class="btn primary" href="#today">开始今日练习</a></div>'}</section>${records.length>30?`<div class="pagination"><button class="btn" data-action="history-prev" ${historyPage===1?'disabled':''}>上一页</button><span>${historyPage}/${Math.ceil(records.length/30)}</span><button class="btn" data-action="history-next" ${historyPage*30>=records.length?'disabled':''}>下一页</button></div>`:''}`,'history');}
function settings(){shell(`<div class="page-heading"><div><h1>让计划跟着你的节奏。</h1><p>题库固定，开始日期可调。${remote.active?'学习进度和照片保存在服务器。换浏览器后，使用同一访问口令进入即可继续。':'记录只保存在当前设备的当前浏览器，不会自动同步。'}</p></div></div><section class="paper settings-panel"><h2>50天计划</h2><p>每科100题，五轮完整作答，每天每科10道。日均建议约11.4小时，含60分钟订正，休息另计。调整开始日期只移动日历，不改动已有练习记录。</p><div class="settings-row"><label for="start-date">开始日期</label><input type="date" id="start-date" value="${state.start}" min="2020-01-01" max="2100-12-31"><button class="btn primary" data-action="save-date">保存日期</button></div><p class="small" style="margin-top:14px">结束日期：${dateFor(50)}。当前选择第${selectedDay}天。</p></section><section class="paper settings-panel"><h2>备份与换设备</h2><p>导出文件包含作答照片、历史文字草稿、自评、错题、收藏、背诵进度、回忆草稿和计划日期。${remote.active?'同一服务器的设备共享同一份学习库；导出用于另存备份或迁往另一台服务器。':'换设备或换浏览器后导入即可继续。'}导入时合并练习记录、收藏与草稿，同一条记录不重复计数；导入草稿会覆盖同题当前草稿。</p><div class="actions"><button class="btn primary" data-action="export">导出进度备份</button>${photoExportUnavailable?'<button class="btn" data-action="export-progress">仅导出学习进度（不含照片）</button>':''}<button class="btn" data-action="import">导入备份</button><input type="file" id="import-file" accept="application/json,.json" class="visually-hidden" tabindex="-1"></div><p class="small" style="margin-top:15px">当前 ${state.records.length}次作答，${Object.values(state.drafts).filter(Boolean).length}份草稿，${state.favorites.length}道收藏，${Object.keys(state.recallProgress).length}张背诵自评，${Object.values(state.recallDrafts).filter(Boolean).length}份回忆草稿。建议定期导出。</p></section>${remote.active?'<section class="paper settings-panel migration-panel"><h2>迁移本机旧数据</h2><p>将更新前保存在本浏览器的进度和照片合并到服务器。会先显示数量供你确认，原本机数据仍保留。</p><button class="btn" data-action="migrate-local">检查并迁移本机旧数据</button><p class="small">迁移入口只能读取当前网站地址下的旧数据。若更换过网址或端口，请在旧地址导出完整JSON，再到这里导入。</p></section>':''}<section class="paper settings-panel"><h2>练习方式</h2><p>计算与论述题由你对照解答自行评估。“会做”表示最近一次自评已掌握；“不熟”和“不会”进入错题复做。自由练习不自动补记计划日，避免把前一轮作答算作下一轮完成。</p><p>题库含三科各100道独立题。所有题干、提纲、完整解答、条件与易错均来自本轮已交付题库，网页只改变呈现方式。</p></section>`,'settings');}
function render(){const p=route();if(p==='practice')practice();else if(p==='today')home();else if(['bank','wrong','favorites'].includes(p))library(p);else if(['recall','recall-study','review'].includes(p))learning.render(p);else if(p==='materials')materials();else if(p==='history')history();else settings();}
async function exportData(progressOnly=false){
 const action=progressOnly?'export-progress':'export';if(!beginOperation(action,'正在准备学习备份…'))return;const opener=document.querySelector('[data-action="'+action+'"]');flushDraft();pause();
 try{
  if(remote.active&&!progressOnly){showOperation('正在等待图片和学习进度保存到服务器…');await photos.whenIdle();await remote.flush();const a=document.createElement('a');a.href=remote.url('api/backup');a.download='';a.click();photoExportUnavailable=false;finishOperation('完整备份下载已开始，请在浏览器下载列表中查看。');toast('已开始下载服务器完整备份，包含进度与作答照片');return;}
  const photoBackup=progressOnly?null:await photos.exportBackup(),payload={...state,...(progressOnly?{photosExcluded:true}:{photos:photoBackup}),exportedAt:new Date().toISOString()},blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`802练习进度${progressOnly?'-不含照片':''}-${nowDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);if(!progressOnly)photoExportUnavailable=false;render();const message=progressOnly?'已导出学习进度，本份备份不含作答照片':'备份已导出，包含进度与作答照片';finishOperation(message);toast(message);
 }catch(error){photoExportUnavailable=remote.active||error.code==='PHOTO_STORAGE_UNAVAILABLE';render();const message=photoExportUnavailable?(remote.active?'服务器完整备份未能开始。请先处理未同步修改，或仅导出学习进度（不含照片）。':'照片存储无法读取。可重试，或选择仅导出学习进度（不含照片）。'):(error.message||'照片备份未能读取，请重试');finishOperation(message,true);toast(message);}
 finally{operation.busy=false;mountOperation();window.StudyUI.restoreFocus(opener);}
}
function confirmImport(imported,total,onConfirm){
 return window.StudyUI.confirm({title:'确认合并备份',confirmText:'合并导入',returnTo:document.querySelector('[data-action="'+(operation.action==='migrate-local'?'migrate-local':'import')+'"]'),fallback:'#main h1',onConfirm,body:`<p>合并后共有 <strong>${total}</strong> 次作答。同一条记录按最近修改保留，收藏取并集。</p><p>备份含 ${Object.values(imported.drafts).filter(Boolean).length} 份草稿；同题当前草稿将以备份为准。计划开始日期将改为 ${esc(imported.start)}。</p><p>备份含 ${Object.keys(imported.recallProgress).length} 张背诵自评、${Object.values(imported.recallDrafts).filter(Boolean).length} 份回忆草稿。背诵自评保留较新的时间；同卡草稿以导入文件为准。</p><p>备份含 ${imported.photoCount||0} 张作答照片。图片将合并保留，取消不写入图片。</p><p class="muted small">建议先导出一份当前备份。</p>`});
}
async function importData(file,{locked=false}={}){
 if(!file)return;if(!locked&&!beginOperation('import','正在检查备份文件…'))return;
 let attempted=false,completedMessage='',completedError=false;
 try{
  if(file.size>145*1024*1024)throw Error('文件过大，请选择本网站导出的备份');
  showOperation('正在读取并检查备份格式…',{done:0,total:0});const rawBackup=JSON.parse(await file.text()),imported=validate(rawBackup),photoItems=await photos.prepareImport(rawBackup.photos,Object.keys(byId),(done,total)=>showOperation(`正在检查作答照片（${done}/${total}）…`,{done,total}));imported.photoCount=photoItems.length;flushDraft();pause();
  const records=new Map(state.records.map(r=>[r.id,r]));for(const r of imported.records){const previous=records.get(r.id);if(!previous||(r.updatedAt||r.at)>(previous.updatedAt||previous.at))records.set(r.id,r);}if(records.size>20000)throw Error('合并后记录过多，未导入。');
  showOperation('备份检查完成，请在预览中确认是否合并。',{done:photoItems.length,total:photoItems.length});
  const accepted=await confirmImport(imported,records.size,async()=>{
   attempted=true;showOperation(remote.active?'正在准备合并到服务器…':'正在合并照片与学习进度…',{state:'pending',done:0,total:photoItems.length});
   try{
    if(remote.active){await photos.whenIdle();await remote.importBackup(imported,photoItems,progress=>showOperation(progress.phase==='upload'?`正在上传备份照片（${progress.done}/${progress.total}）…`:(progress.total?'照片上传完成，正在提交学习记录…':'正在提交学习记录…'),{done:progress.done,total:progress.total}));selectedDay=todayDay();render();completedMessage=`已合并到服务器，共${state.records.length}次作答`;return;}
    await photos.mergeImport(photoItems);state={...state,start:imported.start,records:[...records.values()].sort((a,b)=>a.at-b.at),drafts:{...state.drafts,...imported.drafts},favorites:[...new Set([...state.favorites,...imported.favorites])],session:state.session||imported.session,reading:imported.reading,recallProgress:window.LearningData.merge(state.recallProgress,imported.recallProgress),recallDrafts:{...state.recallDrafts,...imported.recallDrafts},recallSession:state.recallSession||imported.recallSession};const saved=save();completedError=!saved;selectedDay=todayDay();render();completedMessage=saved?`已合并备份，共${state.records.length}次作答`:photoItems.length?'照片已导入，学习进度未能保存，请立即导出备份':'学习进度仅保留在本次页面，未能保存，请立即导出备份';
   }catch(error){showOperation('本次合并未能确认完成，请重试；也可以取消后刷新核对。',{state:'error'});throw error;}
  });
  if(accepted){finishOperation(completedMessage,completedError);toast(completedMessage);}else finishOperation(attempted?'合并结果尚未确认，请刷新核对后再继续。':'已取消导入，当前记录和照片未改动。',attempted);
 }catch(error){const message=error instanceof SyntaxError?'备份文件无法解析，请选择本网站导出的JSON。':error.message||'无法读取备份，原记录未改动';finishOperation(message,true);toast(message);}
 finally{operation.busy=false;mountOperation();}
}
async function finishPractice(){
 const session=state.session;if(!session)return;const wasRunning=!!session.startedAt;pause();rememberQuestion();const rated=session.ids.filter(id=>session.work?.[id]?.ratingId).length,remaining=session.ids.length-rated;
 if(remaining&&!await window.StudyUI.confirm({title:'结束本组练习？',confirmText:'结束本组',cancelText:'继续作答',fallback:'#main h1',body:`<p>本组已自评 <strong>${rated}/${session.ids.length}</strong> 道，还有 <strong>${remaining}</strong> 道未自评。</p><p>结束后保留已有照片、记录和草稿。未自评的题不计完成，之后仍可从题库进入。</p>`})){if(state.session===session&&route()==='practice'){if(wasRunning){session.startedAt=Date.now();save();}practice();}return;}
 if(state.session!==session)return;state.session=null;save();navigate(session.day?'today':'history');toast(`本组已结束，已自评${rated}/${session.ids.length}道。`);
}
root.addEventListener('input',e=>{learning.input(e);if(e.target.id==='draft'){const s=state.session;if(s){state.drafts[s.ids[s.index]]=e.target.value;save();document.getElementById('draft-status').textContent=storageOK?'草稿已保存':'未能保存，请导出备份';}}if(e.target.id==='search'&&!e.isComposing){filter.search=e.target.value;filter.page=1;const pos=e.target.selectionStart;library(route());const el=document.getElementById('search');el.focus();try{el.setSelectionRange(pos,pos);}catch{}}});
root.addEventListener('compositionend',e=>{if(['search','recall-search'].includes(e.target.id))e.target.dispatchEvent(new Event('input',{bubbles:true}));});
root.addEventListener('change',e=>{photos.handleChange(e);learning.change(e);if(e.target.id==='reading-face'){state.reading.face=e.target.value==='sans'?'sans':'serif';save();applyReading();}if(e.target.id==='day-select'){selectedDay=Number(e.target.value);home();}if(e.target.id==='group-filter'){filter.group=e.target.value;filter.page=1;library(route());}if(e.target.id==='status-filter'){filter.status=e.target.value;filter.page=1;library(route());}if(e.target.id==='import-file'){const file=e.target.files[0];e.target.value='';importData(file);}if(['group-filter','status-filter','recall-kind','recall-chapter','recall-status'].includes(e.target.id))window.StudyUI.restoreFocus(e.target);});
root.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,s=state.session;
 photos.handleClick(b);
 learning.action(b);
 if(a==='font-size'){flushDraft();state.reading.size=Number(b.dataset.size);save();applyReading();for(const button of root.querySelectorAll('[data-action="font-size"]')){const selected=Number(button.dataset.size)===state.reading.size;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));}}
 if(a==='focus'){flushDraft();state.reading.focus=!state.reading.focus;save();applyReading();b.textContent=state.reading.focus?'退出专注':'专注阅读';b.setAttribute('aria-pressed',String(state.reading.focus));}
 if(a==='read-question')readingLocation('question-heading');
 if(a==='read-draft')readingLocation('my-writing');
 if(a==='day-prev'||a==='day-next'){selectedDay=Math.max(1,Math.min(50,selectedDay+(a==='day-next'?1:-1)));home();}
 if(a==='today'){selectedDay=todayDay();home();}
 if(a==='resume')navigate('practice');
 if(a==='start-day'||a==='day-question'){const ids=D.plan.days[selectedDay-1][b.dataset.sub+'_refs'];const index=a==='day-question'?ids.indexOf(b.dataset.id):Math.max(0,ids.findIndex(id=>!dayRecord(id,selectedDay)));start(ids,sub[b.dataset.sub].name+'每日10题',selectedDay,index);}
 if(a==='subject'){filter={...filter,subject:b.dataset.sub,group:'all',page:1};library(route());}
 if(a==='favorite'){flushDraft();const id=b.dataset.id;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();toast(state.favorites.includes(id)?'已收藏':'已取消收藏');}
 if(a==='single')start([b.dataset.id],'自由练习');
 if(a==='clear-filter'){filter={...filter,group:'all',status:'all',search:'',page:1};library(route());}
 if(a==='start-filter'||a==='random'){let ids=filtered(route()).map(q=>q.id);if(a==='random'){for(let i=ids.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]];}ids=ids.slice(0,10);}if(ids.length)start(ids,sub[filter.subject].name+(a==='random'?'随机10题':'专题练习'));}
 if(a==='prev-page'||a==='next-page'){filter.page+=a==='next-page'?1:-1;library(route());window.scrollTo({top:0});}
 if(a==='jump')move(Number(b.dataset.index));
 if(a==='prev')move(s.index-1);
 if(a==='next'){if(s.index<s.ids.length-1)move(s.index+1);else finishPractice();}
 if(a==='back')navigate(s.day?'today':'bank');
 if(a==='timer'){flushDraft();if(s.startedAt)pause();else{s.startedAt=Date.now();save();}practice();}
 if(a==='hint'){flushDraft();s.hint=!s.hint;save();practice();}
 if(a==='reveal'){flushDraft();pause();s.revealed=!s.revealed;save();practice();if(s.revealed)readingLocation('answer');else readingLocation('my-writing');}
 if(a==='rate'&&s?.revealed){flushDraft();pause();let r=s.ratingId?state.records.find(r=>r.id===s.ratingId):null;if(!r){r={id:uid(),qid:s.ids[s.index],day:s.day,at:Date.now(),updatedAt:Date.now(),seconds:elapsed(),rating:Number(b.dataset.rating)};state.records.push(r);s.ratingId=r.id;}else{r.rating=Number(b.dataset.rating);r.updatedAt=Date.now();}save();practice();document.querySelector('.self-check')?.scrollIntoView({block:'center'});toast('已记录：'+gradeText(r.rating));}
 if(a==='save-date'){const value=document.getElementById('start-date').value;if(!validDate(value)||value<'2020-01-01'||value>'2100-12-31'){toast('请选择2020至2100年之间的有效日期');return;}state.start=value;selectedDay=todayDay();save();settings();toast('计划日期已更新，练习记录保留');}
 if(a==='export')exportData();
 if(a==='export-progress')exportData(true);
 if(a==='import')document.getElementById('import-file').click();
 if(a==='migrate-local')migrateLocal();
 if(a==='history-prev'||a==='history-next'){historyPage+=a==='history-next'?1:-1;history();}
 if(['favorite','subject','clear-filter','hint','rate','save-date','recall-subject','recall-clear','recall-rate','day-prev','day-next','today'].includes(a))window.StudyUI.restoreFocus(b,'#main h1');
 if(a==='reveal'){if(state.session?.revealed){const heading=root.querySelector('.answer-section h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}else window.StudyUI.restoreFocus(b);}
});
window.addEventListener('hashchange',()=>{pause();render();window.scrollTo({top:0});root.querySelector('h1')?.focus({preventScroll:true});});
document.addEventListener('visibilitychange',()=>{if(document.hidden){flushDraft();pause();}else if(route()==='practice')practice();else if(route()==='recall-study')learning.render('recall-study');});
window.addEventListener('beforeunload',()=>{flushDraft();pause();});
setInterval(()=>{const el=document.getElementById('timer');if(el)el.textContent=clockText(elapsed());},1000);
const photos=window.createPhotoAnswers({remote,root,getQuestionId:()=>route()==='practice'?state.session?.ids[state.session.index]:null,toast});
const learning=window.createLearning({data:D,state:()=>state,canSave:()=>remote.active?remote.status==='saved':storageOK,persistenceMessage:remote.active?persistenceMessage:null,save,esc,shell,navigate,readingBar,toast,nowDate,browseGroup:(subject,group)=>{filter={subject,group,status:'all',search:'',page:1};navigate('bank');},openWrong:subject=>{filter={subject,group:'all',status:'all',search:'',page:1};navigate('wrong');}});
remote.subscribe((next,reset)=>{if(next){if(!reset){next.session=state.session;next.recallSession=state.recallSession;next.reading=state.reading;}state=next;if(reset){selectedDay=todayDay();render();}}for(const el of document.querySelectorAll('[data-server-save-label]'))el.textContent=remote.message;});
async function migrateLocal(){
 if(!beginOperation('migrate-local','正在检查本机旧数据…'))return;
 try{const raw=localStorage.getItem(KEY),backup=await photos.exportLocalBackup();if(!raw&&!backup.items.length){finishOperation('本浏览器未找到旧版学习进度或照片。其他浏览器的数据请先导出JSON。');toast('本浏览器未找到旧版学习进度。其他浏览器的数据请先导出JSON。');return;}const old=raw?validate(JSON.parse(raw)):{...fresh(),start:state.start};await importData(new File([JSON.stringify({...old,photos:backup})],'本机旧数据.json',{type:'application/json'}),{locked:true});}
 catch(error){const message=error.message||'旧数据读取失败，请在原浏览器导出完整备份';finishOperation(message,true);toast(message);}finally{operation.busy=false;mountOperation();}
}
render();
})().catch(error=>{if(error.auth){location.replace(new URL('_access/login',document.baseURI));return;}window.StudyUI.loadError(document.getElementById('app'),error.message);});
